<template><view class="user-card"><image v-if="avatar" class="avatar" :src="avatar" mode="aspectFill" @tap.stop="$emit('avatar-tap')"/><view v-else class="avatar placeholder" @tap.stop="$emit('avatar-tap')"><ui-icon name="user" :size="66" tone="muted"/></view><view class="copy"><view class="name-row"><text class="name">{{name}}</text><text v-if="badge" class="badge">{{badge}}</text></view><text class="meta">UID {{uid}}　｜　经验值 {{experience}}</text><view class="labels"><text>{{gender}}</text><text>{{level}}</text><text v-if="personality">{{personality}}</text></view></view><navigator v-if="settings" class="settings" url="/pages/settings/index" hover-class="tap-active"><text>设置</text><ui-icon name="chevron-right" :size="28" tone="white"/></navigator></view></template>
<script>export default{emits:['avatar-tap'],props:{avatar:{type:String,default:''},name:{type:String,default:''},badge:{type:String,default:'OD'},uid:{type:[String,Number],default:''},experience:{type:[String,Number],default:0},gender:{type:String,default:''},level:{type:String,default:''},personality:{type:String,default:''},settings:{type:Boolean,default:true}}}</script>
<style scoped>.user-card{position:relative;display:flex;align-items:center;gap:22rpx;color:#fff}.avatar{width:132rpx;height:132rpx;flex-shrink:0;border:6rpx solid rgba(255,255,255,.8);border-radius:50%;background:#edf0f5}.placeholder{display:flex;align-items:center;justify-content:center}.copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:10rpx}.name-row{display:flex;align-items:center;gap:12rpx}.name{max-width:260rpx;font-size:30rpx;font-weight:800;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.badge{padding:2rpx 10rpx;border-radius:8rpx;background:#38d779;color:#fff;font-size:21rpx;font-weight:800}.meta{font-size:21rpx}.labels{display:flex;gap:10rpx}.labels text{padding:4rpx 12rpx;border-radius:16rpx;background:rgba(255,255,255,.18);font-size:20rpx}.settings{display:flex;align-items:center;color:#fff;font-size:25rpx}</style>
